CREATE OR REPLACE FUNCTION public.enforce_free_response_allowance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  used integer;
  month_start timestamptz;
begin
  if not coalesce(new.used_free_allowance, false) then
    return new;
  end if;
  -- One company at a time, so two responses sent at once can't both take the last one.
  perform pg_advisory_xact_lock(hashtextextended('pmrfp-free-responses:' || new.trade_organization_id::text, 0));
  month_start := date_trunc('month', now() at time zone 'America/Toronto') at time zone 'America/Toronto';
  select count(*) into used
    from public.rfp_interests
   where trade_organization_id = new.trade_organization_id
     and used_free_allowance
     and created_at >= month_start;
  if used >= 3 then
    raise exception 'free response limit reached' using errcode = 'P0001', hint = 'pmrfp_free_limit';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_town_invite_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  used integer;
  day_start timestamptz;
begin
  if new.status <> 'sent' then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('pmrfp-town-invites:' || new.organization_id::text, 0));
  day_start := date_trunc('day', now() at time zone 'America/Toronto') at time zone 'America/Toronto';
  select count(*) into used
    from public.town_invites
   where organization_id = new.organization_id
     and status = 'sent'
     and created_at >= day_start;
  if used >= 50 then
    raise exception 'town invite limit reached' using errcode = 'P0001', hint = 'pmrfp_town_invite_cap';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.follow_buyer(p_user uuid, p_org uuid, p_key text, p_limit integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  used integer;
begin
  -- One person at a time, so two follows sent at once can't both take the last free slot.
  perform pg_advisory_xact_lock(hashtextextended('pmrfp-buyer-follows:' || p_user::text, 0));
  if exists (select 1 from public.buyer_follows where user_id = p_user and buyer_slug = p_key) then
    return 'already';
  end if;
  if p_limit is not null then
    select count(*) into used from public.buyer_follows where user_id = p_user;
    if used >= p_limit then
      return 'limit';
    end if;
  end if;
  insert into public.buyer_follows (user_id, org_id, buyer_slug) values (p_user, p_org, p_key)
  on conflict (user_id, buyer_slug) do nothing;
  return 'followed';
end;
$function$

CREATE OR REPLACE FUNCTION public.forum_posts_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; cid uuid;
begin
  r := coalesce(new, old);
  perform public.forum_refresh_thread(r.thread_id);
  select category_id into cid from public.forum_threads where id = r.thread_id;
  if cid is not null then perform public.forum_refresh_category(cid); end if;
  perform public.forum_refresh_profile(r.author_id);
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.forum_threads_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op <> 'DELETE' then
    perform public.forum_refresh_thread(new.id);
    perform public.forum_refresh_category(new.category_id);
    perform public.forum_refresh_profile(new.author_id);
  end if;
  if tg_op <> 'INSERT' then
    perform public.forum_refresh_category(old.category_id);
  end if;
  if tg_op = 'DELETE' then perform public.forum_refresh_profile(old.author_id); end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.forum_votes_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pid uuid;
begin
  pid := coalesce(new.post_id, old.post_id);
  update public.forum_posts set upvote_count = (select count(*) from public.forum_post_votes where post_id = pid) where id = pid;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.guard_organization_link_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  member_edit boolean := auth.uid() is not null and not public.is_admin(auth.uid());
begin
  if tg_op = 'INSERT' then
    if member_edit then
      new.link_trusted := false;
      new.link_paid := false;
      new.link_badge := false;
      new.link_earned_at := null;
      new.risk_flagged := false;
      new.email_domain_verified := false;
      new.profile_indexable := true;
    end if;
    return new;
  end if;
  if member_edit and (
    new.link_trusted is distinct from old.link_trusted
    or new.link_paid is distinct from old.link_paid
    or new.link_badge is distinct from old.link_badge
    or new.link_earned_at is distinct from old.link_earned_at
    or new.risk_flagged is distinct from old.risk_flagged
    or new.email_domain_verified is distinct from old.email_domain_verified
    or new.profile_indexable is distinct from old.profile_indexable
  ) then
    raise exception 'Only an administrator can change link and spam-check fields';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_organization_privileged()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or public.is_admin(auth.uid()) then
    return new;
  end if;
  if new.profile_status is distinct from old.profile_status
     and new.profile_status not in ('draft', 'pending_review') then
    raise exception 'Only an administrator can set profile_status to %', new.profile_status;
  end if;
  if new.status is distinct from old.status then
    raise exception 'Only an administrator can change organization status';
  end if;
  if new.verified is distinct from old.verified then
    raise exception 'Only an administrator can change verification';
  end if;
  if new.featured is distinct from old.featured then
    raise exception 'Only an administrator can change featured status';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_rfp_post_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
begin
  -- The service role, SQL jobs (no signed-in user) and admins: unchanged.
  if uid is null or public.is_admin(uid) then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.status not in ('draft', 'pending_review') or new.published_at is not null then
      raise exception 'A new listing waits for PMRFP review' using errcode = '42501';
    end if;
    return new;
  end if;
  if new.status is distinct from old.status and new.status in ('published', 'rejected') then
    raise exception 'Only PMRFP review can publish or reject a listing' using errcode = '42501';
  end if;
  if new.published_at is distinct from old.published_at then
    raise exception 'Only PMRFP review can publish a listing' using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_sealed_interest()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if exists (select 1 from public.rfp_posts r where r.id = new.rfp_id and r.sealed)
    and coalesce(current_setting('pmrfp.sealed_opening', true), '') <> new.rfp_id::text then
    raise exception 'Quotes on this job are sealed until closing' using errcode = 'P0001', hint = 'pmrfp_sealed';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_sealed_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.sealed is distinct from old.sealed then
    if old.status not in ('draft', 'pending_review')
      or exists (select 1 from sealed_box.quotes q where q.rfp_id = old.id) then
      raise exception 'A post''s sealed setting is fixed once it is live' using errcode = '42501', hint = 'pmrfp_sealed_fixed';
    end if;
  end if;
  if old.sealed then
    if new.buyer_key is distinct from old.buyer_key then
      raise exception 'A sealed post keeps its town' using errcode = '42501', hint = 'pmrfp_sealed_fixed';
    end if;
    if new.deadline is distinct from old.deadline
      and (now() >= public.town_closes_at(old.deadline, old.buyer_key)
           or exists (select 1 from sealed_box.openings o where o.rfp_id = old.id and o.status in ('requested', 'opened'))) then
      raise exception 'The sealed box has closed: its closing date can''t move' using errcode = '42501', hint = 'pmrfp_sealed_closed';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_town_answer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.status = 'answered' and (
    new.answer is distinct from old.answer
    or new.public_question is distinct from old.public_question
    or new.question is distinct from old.question
    or new.status is distinct from old.status
  ) then
    raise exception 'A question is answered once' using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_town_interest()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  src text;
  kind text;
begin
  select source_type, post_kind into src, kind from public.rfp_posts where id = new.rfp_id;
  if src = 'public_buyer_direct' then
    if kind = 'tender_mirror' then
      raise exception 'Bids on this tender go to the official portal' using errcode = 'P0001', hint = 'pmrfp_official_portal';
    end if;
    -- Responding to a public buyer is always free: never one of the 3 a month.
    new.used_free_allowance := false;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_town_job_results()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.recommended_interest_id is not null
    and not exists (select 1 from public.rfp_interests i where i.id = new.recommended_interest_id and i.rfp_id = new.rfp_id) then
    raise exception 'Recommend one of this post''s own responses' using errcode = '23514';
  end if;
  if new.award_interest_id is not null
    and not exists (select 1 from public.rfp_interests i where i.id = new.award_interest_id and i.rfp_id = new.rfp_id) then
    raise exception 'Award one of this post''s own responses' using errcode = '23514';
  end if;
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_town_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
begin
  if uid is null or public.is_admin(uid) then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.source_type = 'public_buyer_direct' then
    if new.source_type is distinct from old.source_type
      or new.buyer_key is distinct from old.buyer_key
      or new.buyer_name is distinct from old.buyer_name
      or new.post_kind is distinct from old.post_kind
      or new.official_url is distinct from old.official_url
      or new.posted_by_organization_id is distinct from old.posted_by_organization_id then
      raise exception 'A town''s post keeps its town and kind' using errcode = '42501';
    end if;
    if new.deadline is distinct from old.deadline or new.question_deadline is distinct from old.question_deadline then
      raise exception 'Change a town''s dates with an addendum' using errcode = '42501';
    end if;
    return new;
  end if;
  if new.source_type is distinct from 'public_buyer_direct' then
    return new;
  end if;
  -- A new town post (or a listing turned into one): the poster's own public-buyer organization and page.
  if new.posted_by_organization_id is null
    or not public.is_org_member(uid, new.posted_by_organization_id)
    or not exists (select 1 from public.organizations o where o.id = new.posted_by_organization_id and o.organization_type = 'public_buyer') then
    raise exception 'Only a public buyer posts as a town' using errcode = '42501';
  end if;
  if not exists (select 1 from public.buyer_pages p where p.buyer_key = new.buyer_key and p.organization_id = new.posted_by_organization_id)
    and not exists (select 1 from public.buyer_claims c where c.buyer_key = new.buyer_key and c.user_id = uid and c.status in ('pending', 'verified')) then
    raise exception 'Post as your own town''s page' using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_users_profile_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Service role / trigger context (no auth.uid()) and admins may set any role.
  if auth.uid() is null or public.is_admin(auth.uid()) then
    return new;
  end if;
  if new.primary_role in ('admin', 'super_admin') then
    raise exception 'Not authorized to set primary_role';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_users_profile_privileged()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or public.is_admin(auth.uid()) then
    return new;
  end if;
  if new.primary_role is distinct from old.primary_role then
    raise exception 'Not authorized to change primary_role';
  end if;
  if new.status is distinct from old.status then
    raise exception 'Not authorized to change account status';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.marketplace_listings_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  privileged boolean := coalesce(auth.role(), '') = 'service_role' or public.is_admin(auth.uid());
begin
  if privileged then
    return new;
  end if;
  if tg_op = 'INSERT' then
    new.featured_until := null;
    new.views := 0;
    new.expires_at := now() + interval '60 days';
    if new.status not in ('draft','active') then
      new.status := 'active';
    end if;
    return new;
  end if;
  new.featured_until := old.featured_until;
  new.views := old.views;
  new.user_id := old.user_id;
  if old.status = 'removed' then
    raise exception 'This listing was removed by PMRFP.';
  end if;
  if new.status = 'removed' then
    new.status := old.status;
  end if;
  if new.expires_at > now() + interval '60 days' then
    new.expires_at := now() + interval '60 days';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.purge_site_tracking(p_months integer DEFAULT 13)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- Never shorter than 13 months, whatever the caller passes.
  cutoff timestamptz := now() - make_interval(months => greatest(13, coalesce(p_months, 13)));
  n_events integer;
  n_visitors integer;
  n_pages integer;
  n_referrers integer;
  n_views integer;
begin
  delete from public.site_events where created_at < cutoff;
  get diagnostics n_events = row_count;
  delete from public.site_visitors where day < cutoff::date;
  get diagnostics n_visitors = row_count;
  delete from public.site_page_views where day < cutoff::date;
  get diagnostics n_pages = row_count;
  delete from public.site_referrers where day < cutoff::date;
  get diagnostics n_referrers = row_count;
  -- Only the per-visitor rows this tracking writes.
  delete from public.rfp_views where visitor_hash is not null and created_at < cutoff;
  get diagnostics n_views = row_count;
  return jsonb_build_object('cutoff', cutoff, 'events', n_events, 'visitors', n_visitors, 'pages', n_pages, 'referrers', n_referrers, 'views', n_views);
end;
$function$

CREATE OR REPLACE FUNCTION public.rate_limit_hit(p_key text, p_window_seconds integer, p_limit integer)
 RETURNS TABLE(allowed boolean, hits integer, reset_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  w timestamptz := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  n integer;
begin
  insert into public.rate_limit_hits as r (key, window_start, hits)
  values (p_key, w, 1)
  on conflict (key, window_start) do update set hits = r.hits + 1
  returning r.hits into n;

  -- Opportunistic cleanup (~1% of calls): drop windows older than a day.
  if random() < 0.01 then
    delete from public.rate_limit_hits where window_start < now() - interval '1 day';
  end if;

  return query select n <= p_limit, n, w + make_interval(secs => p_window_seconds);
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.sealed_box_state(p_rfp uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor uuid := sealed_box.actor(p_actor);
  r record;
  op sealed_box.openings%rowtype;
  closes timestamptz;
  received integer;
  withdrawn integer;
  opening jsonb := null;
begin
  select id, sealed, deadline, buyer_key, posted_by_user_id, posted_by_organization_id into r from public.rfp_posts where id = p_rfp;
  if not found or not r.sealed then return null; end if;
  if actor is null or not (public.is_org_member(actor, r.posted_by_organization_id) or actor = r.posted_by_user_id or public.is_admin(actor)) then
    return null;
  end if;
  closes := public.town_closes_at(r.deadline, r.buyer_key);
  select count(*) filter (where status in ('active', 'opened')), count(*) filter (where status = 'withdrawn')
    into received, withdrawn from sealed_box.quotes where rfp_id = p_rfp;
  select * into op from sealed_box.openings where rfp_id = p_rfp;
  if found then
    opening := jsonb_build_object(
      'status', case when op.status = 'requested' and now() > op.expires_at then 'expired' else op.status end,
      'attempt', op.attempt,
      'requested_by', op.requested_by,
      'requested_by_name', sealed_box.person_name(op.requested_by),
      'requested_at', op.requested_at,
      'expires_at', op.expires_at,
      'witness_name', op.witness_name,
      'witness_email', op.witness_email,
      'confirmed_by', op.confirmed_by,
      'confirmed_by_name', sealed_box.person_name(op.confirmed_by),
      'confirmed_method', op.confirmed_method,
      'witness_confirmed_name', op.witness_confirmed_name,
      'opened_at', op.opened_at
    );
  end if;
  return jsonb_build_object(
    'sealed', true,
    'closes_at', closes,
    'time_zone', public.town_time_zone(r.buyer_key),
    'closed', closes is not null and now() >= closes,
    'received', received,
    'withdrawn', withdrawn,
    'members', sealed_box.town_size(r.posted_by_organization_id),
    'opening', opening
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.sealed_break_glass(p_rfp uuid, p_actor uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor uuid := sealed_box.actor(p_actor);
  r record;
  reason text := nullif(trim(coalesce(p_reason, '')), '');
  quotes jsonb;
  n integer;
begin
  if actor is null or not public.is_admin(actor) then return jsonb_build_object('ok', false, 'error', 'not_admin'); end if;
  if reason is null or char_length(reason) < 10 or char_length(reason) > 1000 then return jsonb_build_object('ok', false, 'error', 'reason'); end if;
  select id, title, sealed, posted_by_organization_id into r from public.rfp_posts where id = p_rfp;
  if not found or not r.sealed then return jsonb_build_object('ok', false, 'error', 'not_sealed'); end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'quote', q.id, 'status', q.status, 'company', o.name, 'organization_id', q.trade_organization_id,
           'quote_amount', q.quote_amount, 'quote_kind', q.quote_kind, 'start_date', q.start_date,
           'quote_notes', q.quote_notes, 'message', q.message, 'version', q.version, 'updated_at', q.updated_at
         ) order by q.updated_at), '[]'::jsonb), count(*)::integer
    into quotes, n
    from sealed_box.quotes q left join public.organizations o on o.id = q.trade_organization_id
   where q.rfp_id = p_rfp and q.status in ('active', 'opened');
  perform sealed_box.log(p_rfp, actor, 'sealed_break_glass', jsonb_build_object('reason', reason, 'count', n, 'admin', sealed_box.person_name(actor)));
  insert into public.notifications (user_id, type, title, message, link_url)
  select m.user_id, 'sealed_break_glass', 'PMRFP staff looked inside your sealed quote box', left(r.title || ': ' || reason, 500), '/buyer-dashboard/jobs/' || p_rfp::text || '#record'
    from public.organization_members m where m.organization_id = r.posted_by_organization_id;
  return jsonb_build_object('ok', true, 'quotes', quotes, 'count', n);
end;
$function$

CREATE OR REPLACE FUNCTION public.sealed_open_cancel(p_rfp uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor uuid := sealed_box.actor(p_actor);
  r record;
  op sealed_box.openings%rowtype;
begin
  if actor is null then return jsonb_build_object('ok', false, 'error', 'signin'); end if;
  select id, posted_by_organization_id into r from public.rfp_posts where id = p_rfp and sealed for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_sealed'); end if;
  if not sealed_box.town_member(actor, r.posted_by_organization_id) then return jsonb_build_object('ok', false, 'error', 'not_member'); end if;
  select * into op from sealed_box.openings where rfp_id = p_rfp for update;
  if not found or op.status <> 'requested' then return jsonb_build_object('ok', false, 'error', 'no_request'); end if;
  update sealed_box.openings set status = 'cancelled', witness_token_hash = null, updated_at = now() where rfp_id = p_rfp;
  perform sealed_box.log(p_rfp, actor, 'opening_cancelled', '{}'::jsonb);
  return jsonb_build_object('ok', true);
